<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};use Illuminate\Database\Eloquent\SoftDeletes;use Illuminate\Support\Facades\DB;
class Purchase extends Model {use SoftDeletes;protected $fillable=['customer_id','branch_id','served_by','purchased_at','notes'];protected $casts=['purchased_at'=>'date'];
 public function customer():BelongsTo{return $this->belongsTo(Customer::class);}public function branch():BelongsTo{return $this->belongsTo(Branch::class);}public function servedBy():BelongsTo{return $this->belongsTo(User::class,'served_by');}public function items():HasMany{return $this->hasMany(PurchaseItem::class);}public function reminders():HasMany{return $this->hasMany(Reminder::class);}public function histories():HasMany{return $this->hasMany(PurchaseHistory::class)->latest('created_at');}
 public static function generatePurchaseNumber(Branch $b):string{$p="TR-{$b->code}-".now()->format('ym').'-';$last=self::withTrashed()->where('purchase_number','like',$p.'%')->lockForUpdate()->orderByDesc('purchase_number')->value('purchase_number');return $p.str_pad((string)($last?((int)substr($last,-4))+1:1),4,'0',STR_PAD_LEFT);}
 public static function record(array $a,array $items,User $creator):self{return DB::transaction(function()use($a,$items,$creator){$b=Branch::findOrFail($a['branch_id']);$p=new self($a);$p->purchase_number=self::generatePurchaseNumber($b);$p->served_by=$creator->id;$p->save();$total=0;foreach($items as $i){$i['subtotal']=$i['qty']*$i['unit_price'];$total+=$i['subtotal'];$p->items()->create($i);}$p->update(['total_amount'=>$total]);$p->histories()->create(['user_id'=>$creator->id,'action'=>'created','note'=>'Transaksi dicatat','created_at'=>now()]);return $p;});}
}
